card)}.biology-score-lens-row .gb\:biology-card\:\[\.biology-score-lens-row_\&\]\:\[border\:1px_solid_var\(--border\)\]:is([data-biology-card-view],[data-biology-card-view] *){border:1px solid var(--border)}@media (max-width:650px){.biology-score-lens-row .gb\:biology-card\:card-phone\:\[\.biology-score-lens-row_\&\]\:\[padding\:16px\]:is([data-biology-card-view],[data-biology-card-view] *){padding:16px}}.biology-score-lens-row>.gb\:biology-card\:\[\.biology-score-lens-row_\>\&\[open\]\]\:\[overflow\:visible\]:is([data-biology-card-view],[data-biology-card-view] *)[open]{overflow:visible}.biology-score-lens-row>.gb\:biology-card\:\[\.biology-score-lens-row_\>\&\[open\]\]\:\[border-color\:transparent\]:is([data-biology-card-view],[data-biology-card-view] *)[open]{border-color:#0000}.biology-score-lens-row>.gb\:biology-card\:\[\.biology-score-lens-row_\>\&\[open\]\]\:\[background\:transparent\]:is([data-biology-card-view],[data-biology-card-view] *)[open]{background:0 0}.biology-score-lens-row>.biology-score-compact[open]>.gb\:biology-card\:\[\.biology-score-lens-row_\>\.biology-score-compact\[open\]\>\&\]\:\[border-radius\:12px\]:is([data-biology-card-view],[data-biology-card-view] *){border-radius:12px}.biology-score-lens-row>.biology-score-compact[open]>.gb\:biology-card\:\[\.biology-score-lens-row_\>\.biology-score-compact\[open\]\>\&\]\:\[outline\:1px_solid_var\(--accent\)\]:is([data-biology-card-view],[data-biology-card-view] *){outline:1px solid var(--accent)}.biology-score-lens-row>.biology-score-compact[open]>.gb\:biology-card\:\[\.biology-score-lens-row_\>\.biology-score-compact\[open\]\>\&\]\:\[background\:var\(--bg-card\)\]:is([data-biology-card-view],[data-biology-card-view] *){background:var(--bg-card)}.biology-score-unavailable-group .gb\:biology-card\:\[\.biology-score-unavailable-group_\&\]\:\[box-shadow\:none\]:is([data-biology-card-view],[data-biology-card-view] *){box-shadow:none}.biology-score-unavailable-group .gb\:biology-card\:\[\.biology-score