/* Cross-device sync status: keep the primary answer calm and scannable;
   raw CRDT/debug information lives behind the technical disclosure. */
.sync-diagnose-modal {
  width: min(720px, calc(100vw - 28px));
  max-width: 720px;
  max-height: min(860px, calc(100dvh - 28px));
}

.sync-diagnose-modal .modal-header {
  align-items: center;
}

.sync-diagnose-modal .modal-header h3 {
  margin: 1px 0 0;
}

.sync-diagnose-modal-kicker,
.sync-diagnose-card-label,
.sync-diagnose-summary-eyebrow {
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.sync-diagnose-body {
  font-size: 13px;
  overflow-y: auto;
}

.sync-diagnose-summary {
  display: flex;
  gap: 14px;
  margin-bottom: 14px;
  padding: 16px;
  border: 1px solid var(--border);
  border-left-width: 4px;
  border-radius: 10px;
  background: var(--bg-secondary);
}

.sync-diagnose-summary-success {
  border-left-color: var(--green);
}
.sync-diagnose-summary-warning {
  border-left-color: var(--orange);
}
.sync-diagnose-summary-danger {
  border-left-color: var(--red);
}
.sync-diagnose-summary-neutral {
  border-left-color: var(--accent);
}

.sync-diagnose-summary-icon {
  display: grid;
  flex: 0 0 32px;
  width: 32px;
  height: 32px;
  place-items: center;
  border: 1px solid var(--border);
  border-radius: 50%;
  background: var(--surface);
  font-size: 16px;
  font-weight: 800;
}

.sync-diagnose-summary-success .sync-diagnose-summary-icon {
  color: var(--green);
}
.sync-diagnose-summary-warning .sync-diagnose-summary-icon {
  color: var(--orange);
}
.sync-diagnose-summary-danger .sync-diagnose-summary-icon {
  color: var(--red);
}
.sync-diagnose-summary-neutral .sync-diagnose-summary-icon {
  color: var(--accent);
}

.sync-diagnose-summary-content {
  min-width: 0;
}
.sync-diagnose-summary-content h4 {
  margin: 2px 0 5px;
  font-size: 17px;
}
.sync-diagnose-summary-content p,
.sync-diagnose-card-copy,
.sync-diagnose-device-check p,
.sync-diagnose-maintenance p,
.sync-diagnose-row-content p {
  margin: 0;
  color: var(--text-muted);
  line-height: 1.5;
}

.sync-diagnose-summary-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 10px;
}

.sync-diagnose-summary-badges span,
.sync-diagnose-badge {
  padding: 3px 7px;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--surface);
  color: var(--text-secondary);
  font-size: 10px;
  font-weight: 600;
}

.sync-diagnose-badge-success {
  color: var(--green);
  border-color: var(--green);
}
.sync-diagnose-badge-danger {
  color: var(--red);
  border-color: var(--red);
}

.sync-diagnose-device-check {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 16px;
  align-items: center;
  margin-bottom: 12px;
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-radius: 9px;
}

.sync-diagnose-device-title {
  margin: 2px 0 3px;
  font-weight: 650;
}

.sync-diagnose-device-code {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 128px;
  padding: 8px 10px;
  border-radius: 7px;
  background: var(--bg-secondary);
}

.sync-diagnose-device-code span {
  color: var(--text-muted);
  font-size: 10px;
}
.sync-diagnose-device-code strong {
  font-size: 11px;
}

.sync-diagnose-card {
  margin-bottom: 12px;
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-radius: 9px;
}

.sync-diagnose-card-head,
.sync-diagnose-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.sync-diagnose-card-title {
  margin-top: 2px;
  font-size: 14px;
  font-weight: 650;
}
.sync-diagnose-card-copy {
  margin-top: 7px;
  font-size: 12px;
}
.sync-diagnose-card-footer .sync-diagnose-card-copy {
