}

.sync-diagnose-storage-track {
  height: 7px;
  margin: 10px 0 8px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--surface);
}

.sync-diagnose-storage-track span {
  display: block;
  height: 100%;
  border-radius: inherit;
}

.sync-diagnose-technical {
  margin-top: 14px;
  border: 1px solid var(--border);
  border-radius: 9px;
  background: var(--bg-secondary);
}

.sync-diagnose-technical > summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 14px;
  cursor: pointer;
  list-style: none;
  user-select: none;
}

.sync-diagnose-technical > summary::-webkit-details-marker {
