}

.sync-diagnose-technical-content {
  padding: 0 14px 14px;
  border-top: 1px solid var(--border);
}

.sync-diagnose-facts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1px;
  margin: 12px 0;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--border);
}

.sync-diagnose-facts > div {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
  padding: 9px 10px;
  background: var(--surface);
}

.sync-diagnose-facts span {
  color: var(--text-muted);
  font-size: 10px;
}
.sync-diagnose-facts b,
.sync-diagnose-facts code {
  overflow-wrap: anywhere;
  font-size: 11px;
}
.sync-diagnose-fact-wide {
  grid-column: 1 / -1;
}

.sync-diagnose-technical-reason,
.sync-diagnose-row-warning {
  margin: 8px 0;
  padding: 8px 10px;
  border-left: 3px solid var(--orange);
  border-radius: 4px;
  background: var(--surface);
  color: var(--text-secondary);
  font-size: 11px;
}

.sync-diagnose-developer-block {
  margin-top: 12px;
}
.sync-diagnose-section-heading {
  margin: 12px 0 7px;
  font-size: 12px;
  font-weight: 700;
}

.sync-diagnose-row-details {
  margin-top: 10px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--surface);
}

.sync-diagnose-row-details > summary {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding: 9px 10px;
  cursor: pointer;
  color: var(--text-secondary);
  font-size: 11px;
}

.sync-diagnose-row-content {
  padding: 0 10px 10px;
}
.sync-diagnose-table-wrap {
  overflow-x: auto;
}
.sync-diagnose-table-wrap table {
  width: 100%;
  min-width: 590px;
  border-collapse: collapse;
  font-size: 11px;
}
.sync-diagnose-table-wrap th {
  padding: 5px 7px;
  border-bottom: 1px solid var(--border);
  text-align: left;
}
.sync-diagnose-table-wrap td {
  padding: 4px 7px !important;
}
.sync-diagnose-row-content p {
  margin-top: 7px;
  font-size: 10px;
}

.sync-diagnose-maintenance {
  margin-top: 12px;
}
.sync-diagnose-maintenance p {
  font-size: 11px;
}
.sync-diagnose-maintenance-actions,
.sync-diagnose-footer {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.sync-diagnose-maintenance-actions {
  margin-top: 8px;
}
.sync-diagnose-maintenance-actions .ctx-btn-option {
  font-size: 11px;
}
.sync-diagnose-danger-action {
  color: var(--red);
  border-color: var(--red);
}
.sync-diagnose-footer {
  justify-content: flex-end;
  margin-top: 14px;
}

@media (max-width: 560px) {
  .sync-diagnose-modal {
  width: calc(100vw - 20px);
  max-height: calc(100dvh - 20px);
}
  .sync-diagnose-summary {
  padding: 13px;
}
  .sync-diagnose-device-check {
  grid-template-columns: 1fr;
}
  .sync-diagnose-device-code {
  min-width: 0;
}
  .sync-diagnose-card-head,
  .sync-diagnose-card-footer {
  align-items: flex-start;
  flex-direction: column;
}
  .sync-diagnose-refresh,
  .sync-diagnose-storage-action {
  width: 100%;
}
  .sync-diagnose-facts {
  grid-template-columns: 1fr;
}
  .sync-diagnose-fact-wide {
  grid-column: auto;
}
  .sync-diagnose-maintenance-actions .ctx-btn-option {
  width: 100%;
}
}

@media (max-width: 640px) {
  .profile-share-input-row {
  grid-template-columns: minmax(0, 1fr) 38px;
}
  .profile-share-active-row {
  grid-template-columns: 1fr;
  align-items: stretch;
}
  .profile-share-active-actions {
  justify-content: flex-end;
}
}

/* Styled Confirmation Dialog */
.confirm-overlay {
  position: fixed; top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.7); z-index: 1200; display: none;
  align-items: center; justify-content: center;
  padding: 24px;
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
}
.confirm-overlay.show { display: flex; }
.confirm-dialog {
  background: var(--bg-secondary); border-radius: var(--radius);
  border: 1px solid var(--border); padding: 24px 26px;
  max-width: 460px; width: min(100%, 460px); box-shadow: var(--shadow-lg);
}
.confirm-message {
  font-size: 15px; line-height: 1.6; color: var(--text-primary); margin-bottom: 24px;
  white-space: pre-line;
}
.confirm-input {
  box-sizing: border-box;
  width: 100%;
  min-height: 40px;
  margin: 8px 0 14px;
  padding: 9px 11px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  outline: none;
  background: var(--select-surface);
  color: var(--text-primary);
  font: inherit;
  font-size: 13px;
}
.confirm-input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-fill);
}
.confirm-actions { display: flex; gap: 10px; justify-content: flex-end; }
.confirm-btn {
  padding: 8px 18px; border-radius: var(--radius-sm); border: 1px solid transparent;
  font-size: 13px; font-weight: 600; cursor: pointer;
  font-family: inherit; transition: all 0.15s;
}
.confirm-btn-cancel {
  background: var(--bg-card); color: var(--text-secondary); border: 1px solid var(--border);
}
.confirm-btn-cancel:hover { background: var(--bg-hover); color: var(--text-primary); }
.confirm-btn-danger { background: var(--red); color: #fff; border-color: var(--red); }
.confirm-btn-danger:hover { opacity: 0.9; transform: translateY(-1px); }
.confirm-btn-primary { background: var(--accent-gradient); color: #fff; border-color: transparent; }
.confirm-btn-primary:hover { opacity: 0.92; transform: translateY(-1px); }

.modal .modal-unit {
  color: var(--text-muted); font-size: 14px; margin-bottom: 8px;
  /* Source-name + delta + trend separated by middle-dots; let them wrap
     gracefully on narrow viewports rather than overflow the modal box. */
  display: flex; flex-wrap: wrap; gap: 4px 6px; align-items: center;
}
.modal .modal-unit.modal-unit-alt {
  font-size: 12px; opacity: 0.7; margin-top: -4px; margin-bottom: 12px;
}
.modal .wearable-modal-source-swap {
  margin-left: auto;
  font-size: 11px;
}

.ref-editable { cursor: pointer; border-bottom: 1px dashed var(--text-muted); padding-bottom: 1px; }
.ref-editable:hover { color: var(--accent); border-color: var(--accent); }
.ref-edit-field { display: inline-flex; align-items: center; position: relative; }
.ref-edit-input { width: 60px; padding: 2px 20px 2px 6px; font-size: 13px; font-family: var(--font-mono); background: var(--bg-primary); color: var(--text-primary); border: 1px solid var(--border); border-radius: var(--radius-sm); }
.ref-edit-input:focus { border-color: var(--accent); outline: none; }
.ref-edit-clear { position: absolute; right: 2px; top: 50%; transform: translateY(-50%); background: none; border: none; color: var(--text-muted); cursor: pointer; font-size: 14px; padding: 0 3px; line-height: 1; opacity: 0.5; }
.ref-edit-clear:hover { opacity: 1; color: var(--red); }
.ref-edit-save { padding: 2px 8px; font-size: 12px; background: var(--accent-gradient); color: white; border: none; border-radius: var(--radius-sm); cursor: pointer; margin-left: 4px; }
.ref-edited-badge { font-size: 10px; color: var(--yellow); cursor: pointer; margin-left: 4px; opacity: 0.8; }
.ref-edited-badge:hover { opacity: 1; text-decoration: underline; }

.toggle-switch { position: relative; display: inline-block; width: 36px; height: 20px; flex-shrink: 0; }
.toggle-switch input { opacity: 0; width: 0; height: 0; }
.toggle-slider { position: absolute; cursor: pointer; inset: 0; background: var(--border); border-radius: 20px; transition: background 0.2s; }
.toggle-slider::before { content: ''; position: absolute; width: 14px; height: 14px; left: 3px; bottom: 3px; background: var(--text-secondary); border-radius: 50%; transition: transform 0.2s, background 0.2s; }
.toggle-switch input:checked + .toggle-slider { background: var(--accent); }
.toggle-switch input:checked + .toggle-slider::before { transform: translateX(16px); background: #fff; }
.toggle-switch input:focus-visible + .toggle-slider {
  outline: 2px solid color-mix(in srgb, var(--accent) 82%, transparent);
  outline-offset: 3px;
}
.toggle-switch input:disabled + .toggle-slider {
  cursor: not-allowed;
}

.emoji-picker {
  position: fixed;
  z-index: 10001;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-lg);
  width: 320px;
  max-height: 400px;
  display: flex;
  flex-direction: column;
}
.emoji-picker-search {
  padding: 8px;
  border-bottom: 1px solid var(--border);
}
.emoji-picker-search input {
  width: 100%;
  padding: 6px 10px;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: var(--bg-secondary);
  color: var(--text-primary);
  font-size: 14px;
  outline: none;
  box-sizing: border-box;
}
.emoji-picker-search input:focus {
  border-color: var(--accent);
}
.emoji-picker-cats {
  display: flex;
  gap: 2px;
  padding: 4px 8px;
  border-bottom: 1px solid var(--border);
  overflow-x: auto;
  flex-shrink: 0;
}
.emoji-picker-cats button {
  background: none;
  border: none;
  font-size: 16px;
  padding: 4px 6px;
  cursor: pointer;
  border-radius: 4px;
  opacity: 0.6;
}
.emoji-picker-cats button.active, .emoji-picker-cats button:hover {
  opacity: 1;
  background: var(--bg-secondary);
}
.emoji-picker-grid {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 2px;
  padding: 8px;
  overflow-y: auto;
  flex: 1;
}
.emoji-picker-grid span {
  font-size: 22px;
  text-align: center;
  cursor: pointer;
  padding: 4px;
  border-radius: 4px;
  line-height: 1.2;
}
.emoji-picker-grid span:hover {
  background: var(--bg-secondary);
}
.emoji-picker-label {
  grid-column: 1 / -1;
  font-size: 11px;
  color: var(--text-secondary);
  padding: 6px 2px 2px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.emoji-picker-cats button[data-cat="__reset"] {
  font-size: 12px;
  font-family: inherit;
}

@media (max-width: 640px) {
  .modal-overlay { padding: 8px; }
}
@media (max-width: 480px) {
  .confirm-dialog { padding: 22px 18px; }
}
@media (pointer: coarse) {
  .modal-close,
  .context-back-btn { min-width: 44px; min-height: 44px; display: flex; align-items: center; justify-content: center; }
}

