:where(.gb\:feedback-panel\:feedback-panel-block):where(#feedback-modal, #feedback-modal *):is(.feedback-redesign-modal) {
  width: min(94vw, 560px);
  max-width: 560px !important;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
:where(.gb\:feedback-head\:feedback-head-block):where(#feedback-modal, #feedback-modal *):is(.feedback-modal-head) {
  flex-shrink: 0;
}
:where(.gb\:feedback-body\:feedback-body-block):where(#feedback-modal, #feedback-modal *):is(.feedback-form-body) {
  background: transparent;
  overflow-y: auto;
}
:where(.gb\:feedback-form\:feedback-form-block):where(#feedback-modal, #feedback-modal *):is(.feedback-form) {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
:where(.gb\:feedback-field\:feedback-field-block):where(#feedback-modal, #feedback-modal *):is(.feedback-field) {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 6px;
}
:where(.gb\:feedback-field-hidden\:feedback-field-hidden-block):where(#feedback-modal, #feedback-modal *):is(.feedback-field[hidden]) {
  display: none;
}
:where(.gb\:feedback-summary\:feedback-summary-block):where(#feedback-modal, #feedback-modal *):is(#feedback-result summary) {
  cursor: pointer;
  color: var(--text-secondary);
  margin-bottom: 8px;
}
:where(.gb\:feedback-preview\:feedback-preview-block):where(#feedback-modal, #feedback-modal *):is(#feedback-result .feedback-textarea) {
  min-height: 130px;
  margin: 6px 0;
}
:where(.gb\:feedback-label\:feedback-label-block):where(#feedback-modal, #feedback-modal *):is(.feedback-label) {
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
:where(.gb\:feedback-textarea\:feedback-textarea-block):where(#feedback-modal, #feedback-modal *):is(.feedback-textarea) {
  min-height: 160px;
  max-height: min(34vh, 260px);
  resize: vertical;
  line-height: 1.5;
}
:where(.gb\:feedback-notice\:feedback-notice-block):where(#feedback-modal, #feedback-modal *):is(.feedback-notice) {
  margin: 0;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--bg-card) 76%, transparent);
  color: var(--text-muted);
  font-size: 11.5px;
  line-height: 1.5;
}
:where(.gb\:feedback-actions\:feedback-actions-block):where(#feedback-modal, #feedback-modal *):is(.feedback-actions) {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 2px;
  padding-top: 14px;
  border-top: 1px solid var(--border);
}
:where(.gb\:feedback-button\:feedback-button-block):where(#feedback-modal, #feedback-modal *):is(.feedback-form .import-btn) {
  min-height: 38px;
}
@media (max-width: 720px) {
  :where(.gb\:feedback-phone-panel\:feedback-phone-panel-block):where(#feedback-modal, #feedback-modal *):is(.feedback-redesign-modal) {
    width: calc(100vw - 24px);
    max-height: calc(100vh - 24px);
    max-height: calc(100dvh - 24px);
  }
  :where(.gb\:feedback-phone-textarea\:feedback-phone-textarea-block):where(#feedback-modal, #feedback-modal *):is(.feedback-textarea) {
    min-height: 180px;
    max-height: 34vh;
  }
  :where(.gb\:feedback-phone-actions\:feedback-phone-actions-block):where(#feedback-modal, #feedback-modal *):is(.feedback-actions) {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  :where(.gb\:feedback-phone-button\:feedback-phone-button-block):where(#feedback-modal, #feedback-modal *):is(.feedback-form .import-btn) {
    width: 100%;
    min-height: 42px;
  }
