  if (conv) {
    if (conv.type === 'multiply' && targetUnit === conv.usUnit)
      return parseFloat((siValue * conv.factor).toPrecision(6));
    if (conv.type === 'hba1c' && targetUnit === '%')
      return parseFloat(((siValue / 10.929) + 2.15).toFixed(1));
  }
  const secondaries = SECONDARY_UNIT_CONVERSIONS[dotKey];
  if (secondaries) {
    for (const sec of secondaries) {
      if (sec.type === 'multiply' && targetUnit === sec.unit)
        return parseFloat((siValue * sec.factor).toPrecision(6));
      if (sec.type === 'hba1c' && targetUnit === sec.unit)
        return parseFloat(((siValue / 10.929) + 2.15).toFixed(1));
